var names = new[] { "Logging", "Validation", "Transaction" };
Func<string, string> handler = n => { Console.WriteLine("Handler " + n); return "ok"; };
Func<string, string> next = handler;
for (int i = names.Length - 1; i >= 0; i--)
{
    var inner = next; var name = names[i];
    next = req =>
    {
        Console.WriteLine(name + " >");
        try
        {
            if (name == "Validation" && req == "") throw new ArgumentException("Name");
            return inner(req);
        }
        finally { Console.WriteLine(name + " <"); }
    };
}
